previewCss:
.darma-loader-trampoline-bounce {
  position: relative;
  width: 48px;
  height: 48px;
}
.darma-loader-trampoline-bounce::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 8px;
  width: 3px;
  height: 10px;
  background: #c7d2fe;
  box-shadow: 30px 0 0 #c7d2fe;
}
.darma-loader-trampoline-bounce::after {
  content: "";
  position: absolute;
  bottom: 8px;
  left: 4px;
  right: 4px;
  height: 4px;
  border-radius: 3px;
  background: var(--loader-color, #6366f1);
  transform-origin: center;
  animation: darma-loader-trampoline-bounce-mat 0.9s ease-in-out infinite;
}
.darma-loader-trampoline-bounce i {
  position: absolute;
  left: 50%;
  width: 14px;
  height: 14px;
  margin-left: -7px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-trampoline-bounce-bnc 0.9s ease-in-out infinite;
}
@keyframes darma-loader-trampoline-bounce-bnc {
  0%, 100% { top: 2px; }
  50% { top: 24px; }
}
@keyframes darma-loader-trampoline-bounce-mat {
  0%, 38%, 62%, 100% { transform: scaleY(1) translateY(0); }
  50% { transform: scaleY(1.5) translateY(3px); }
}

